dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ бит_ЛицевыеСчета.Идентификатор КАК НомерЗаписи, бит_ЛицевыеСчета.Ссылка КАК ЛицевойСчет, ВЫБОР КОГДА бит_ЛицевыеСчета.КапРемЕЛСГИСЖКХ = "" ТОГДА ВЫБОР КОГДА бит_ЛицевыеСчета.КапРемПрефикс <> "" ТОГДА бит_ЛицевыеСчета.КапРемПрефикс + бит_ЛицевыеСчета.Наименование ИНАЧЕ "КР" + бит_ЛицевыеСчета.Наименование КОНЕЦ ИНАЧЕ бит_ЛицевыеСчета.КапРемЕЛСГИСЖКХ КОНЕЦ КАК НомерЛС, бит_ЛицевыеСчета.Здание КАК Здание, бит_ЛицевыеСчета.Квартира КАК Квартира ПОМЕСТИТЬ ВТ_ЛицевыеСчета ИЗ Справочник.бит_ЛицевыеСчета КАК бит_ЛицевыеСчета ГДЕ бит_ЛицевыеСчета.Архивный = ЛОЖЬ И НЕ бит_ЛицевыеСчета.ПометкаУдаления {ГДЕ (бит_ЛицевыеСчета.Ссылка В (&СписокЛС)), (бит_ЛицевыеСчета.Организация = &ОтборОрганизация), (бит_ЛицевыеСчета.Здание В (&СписокЗданий))}
ИНДЕКСИРОВАТЬ ПО ЛицевойСчет, Здание, Квартира ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ЛицевыеСчета.ЛицевойСчет КАК ЛицевойСчет, ВТ_ЛицевыеСчета.НомерЗаписи КАК НомерЗаписи, ВТ_ЛицевыеСчета.НомерЛС КАК НомерЛС, ВТ_ЛицевыеСчета.Здание КАК Здание, ВТ_ЛицевыеСчета.Квартира КАК Квартира, бит_СписокЗданий.ПочтовыйАдрес КАК ПочтовыйАдрес, ВЫБОР КОГДА ЕСТЬNULL(бит_СписокЗданий.КодФИАС, "") = "" ТОГДА ЕСТЬNULL(бит_СписокЗданий.УникальныйНомерГИСЖКХ, "") ИНАЧЕ ЕСТЬNULL(бит_СписокЗданий.КодФИАС, "") КОНЕЦ КАК КодФИАС_ИдентификаторГИСЖКХ, бит_Квартиры.Наименование КАК НомерПомещения, бит_Квартиры.УникальныйНомерГИСЖКХ КАК УникальныйНомерГИСЖКХ ПОМЕСТИТЬ ВТ_ИнформацияОПомещении ИЗ ВТ_ЛицевыеСчета КАК ВТ_ЛицевыеСчета ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_СписокЗданий КАК бит_СписокЗданий ПО ВТ_ЛицевыеСчета.Здание = бит_СписокЗданий.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Квартиры КАК бит_Квартиры ПО ВТ_ЛицевыеСчета.Квартира = бит_Квартиры.Ссылка ГДЕ НЕ бит_Квартиры.ПометкаУдаления И НЕ бит_СписокЗданий.ПометкаУдаления {ГДЕ (бит_СписокЗданий.Улица В (&СписокУлиц)), (ВЫБОР КОГДА &ТипДомаГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ТОГДА бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ИЛИ бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.ПустаяСсылка) ИНАЧЕ бит_СписокЗданий.ТипыДомовГИСЖКХ В (&ТипДомаГИСЖКХ) КОНЕЦ)}
ИНДЕКСИРОВАТЬ ПО Квартира ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ бит_СведенияОКвартиреСрезПоследних.Квартира КАК Квартира, бит_СведенияОКвартиреСрезПоследних.ТипКвартиры КАК ТипКвартиры ПОМЕСТИТЬ ВТ_ДопСведения ИЗ РегистрСведений.бит_СведенияОКвартире.СрезПоследних( &Период, Квартира В (ВЫБРАТЬ РАЗЛИЧНЫЕ ВТ_ЛицевыеСчета.Квартира ИЗ ВТ_ЛицевыеСчета)) КАК бит_СведенияОКвартиреСрезПоследних
ИНДЕКСИРОВАТЬ ПО Квартира ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ИнформацияОПомещении.НомерЗаписи КАК НомерЗаписи, ВТ_ИнформацияОПомещении.НомерЛС КАК НомерЛС, ЕСТЬNULL(ВТ_ИнформацияОПомещении.ПочтовыйАдрес, "") КАК АдресПомещения, ЕСТЬNULL(ВТ_ИнформацияОПомещении.КодФИАС_ИдентификаторГИСЖКХ, "") КАК КодФИАС_ИдентификаторГИСЖКХ, ЕСТЬNULL(ВТ_ИнформацияОПомещении.НомерПомещения, "") КАК НомерПомещения, ПРЕДСТАВЛЕНИЕ(ЕСТЬNULL(бит_Комнаты.НомерКомнаты, "")) КАК НомерКомнаты, ЕСТЬNULL(ВТ_ИнформацияОПомещении.УникальныйНомерГИСЖКХ, "") КАК УникальныйНомерГИСЖКХ, ВЫБОР КОГДА ВТ_ДопСведения.ТипКвартиры = ЗНАЧЕНИЕ(Справочник.бит_ТипыКвартиры.НежилоеПомещение) ТОГДА "Нежилое помещение" КОГДА ВТ_ДопСведения.ТипКвартиры = ЗНАЧЕНИЕ(Справочник.бит_ТипыКвартиры.БлокВДомеБлокированнойЗастройки) ТОГДА "Блок в доме блокированной застройки" ИНАЧЕ "Жилое помещение" КОНЕЦ КАК ТипПомещенияБлок ИЗ ВТ_ИнформацияОПомещении КАК ВТ_ИнформацияОПомещении ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ДопСведения КАК ВТ_ДопСведения ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Комнаты КАК бит_Комнаты ПО ВТ_ДопСведения.Квартира = бит_Комнаты.Владелец ПО ВТ_ИнформацияОПомещении.Квартира = ВТ_ДопСведения.Квартира
УПОРЯДОЧИТЬ ПО ВТ_ИнформацияОПомещении.НомерЛС
